class LRUCache {
  /**
   * @param {number} capacity
   */
  constructor(capacity) {
    if (capacity < 0) {
      throw new Error('capacity must be non‑negative');
    }
    this.capacity = capacity;
    this.map = new Map(); // key -> { value, prev, next }
    this.head = new Node(); // dummy head (most recent)
    this.tail = new Node(); // dummy tail (least recent)
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * @param {*} key
   * @returns {*}
   */
  get(key) {
    if (this.capacity === 0) return -1;
    const node = this.map.get(key);
    if (!node) return -1;
    this._moveToHead(node);
    return node.value;
  }

  /**
   * @param {*} key
   * @param {*} value
   */
  put(key, value) {
    if (this.capacity === 0) return;

    let node = this.map.get(key);
    if (node) {
      // update existing
      node.value = value;
      this._moveToHead(node);
      return;
    }

    // insert new
    node = new Node(value);
    this.map.set(key, node);
    this._addToHead(node);

    if (this.map.size > this.capacity) {
      // evict least recent (tail.prev)
      const last = this.tail.prev;
      this._remove(last);
      this.map.delete(last.key);
    }
  }

  _addToHead(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }

  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.next = node.prev = null; // help GC
  }

  _moveToHead(node) {
    this._remove(node);
    this._addToHead(node);
  }
}

/** Simple doubly‑linked list node */
class Node {
  constructor(value) {
    this.key = undefined; // set by LRUCache when inserted
    this.value = value;
    this.prev = null;
    this.next = null;
  }
}
